const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Vietnam and Myanmar
  const vietnam = ee.Geometry.Rectangle([102.145, 8.6, 109.646, 23.393]);
  const myanmar = ee.Geometry.Rectangle([92.172, 9.16, 101.869, 28.547]);

  // 2. Define target date
  const targetDate = '2018-02-03';
  const startDate = '2018-02-03';
  const endDate = '2018-02-04';

  // 3. Acquire MODIS Active Fire data (FIRMS)
  const fireCollection = ee.ImageCollection('FIRMS')
    .filterDate(startDate, endDate);

  const fireCollectionSize = fireCollection.size().getInfo();
  console.log(`FIRMS Images on ${targetDate}: ${fireCollectionSize}`);

  if (fireCollectionSize === 0) {
    console.log('No fire data available for this date.');
    console.log('C1');
    return;
  }

  // 4. Count active fire detections in each region
  const fireImage = fireCollection.first();

  // Get fire count for Vietnam
  const vietnamFireCount = fireImage
    .reduceRegion(
      ee.Reducer.count(),
      vietnam,
      1000,
      1e9
    )
    .values()
    .get(0)
    .getInfo();

  // Get fire count for Myanmar
  const myanmarFireCount = fireImage
    .reduceRegion(
      ee.Reducer.count(),
      myanmar,
      1000,
      1e9
    )
    .values()
    .get(0)
    .getInfo();

  console.log(`Vietnam Fire Detections: ${vietnamFireCount}`);
  console.log(`Myanmar Fire Detections: ${myanmarFireCount}`);

  // 5. Validation & Answer
  if (vietnamFireCount === null || myanmarFireCount === null) {
    console.log('C3');
    return;
  }

  if (vietnamFireCount > myanmarFireCount) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
